/* routine.c */
static void SetRegisterField(unsigned int reg, unsigned int offset, unsigned int width, unsigned int value)
{
	unsigned int result;
	unsigned int original;
	unsigned int mask;
	unsigned int value_masked;

	original = *(volatile unsigned int *)reg;

	if (width == 32)
		mask = 0xffffffff;
	else
		mask = (1 << width) - 1;
	value_masked = value & mask;
	result = (original & (~(mask << offset))) | (value_masked << offset);

	*(volatile unsigned int *)reg = result;
}

static unsigned int GetRegisterField(unsigned int reg, unsigned int offset, unsigned int width)
{
	unsigned int result;
	unsigned int original;
	unsigned int mask;
	unsigned int mask_shifted;

	original = *(volatile unsigned int *)reg;
	if(width==32)
		mask = 0xffffffff;
	else
		mask = (1 << width)-1;
	mask_shifted = mask << offset;
	result = (original & mask_shifted) >> offset;

	return result;
}

static void Databahn_SetModeRegister6(unsigned int reg)
{
        //MRSINGLE_DATA_0
        SetRegisterField(Databahn_Reg(DATABAHN_REG_MRSINGLE_DATA_0_ADDR), DATABAHN_REG_MRSINGLE_DATA_0_OFFSET, 8, reg);
        //WRITE_MODEREG6
        SetRegisterField(Databahn_Reg(DATABAHN_REG_WRITE_MODEREG_ADDR), DATABAHN_REG_WRITE_MODEREG_OFFSET, DATABAHN_REG_WRITE_MODEREG_WIDTH, 0x02800006);
}

static void Databahn_SetDDR4Vref(void)
{
	/* ROM has init Counter1, so directly invoke stage1_delay_us */
	unsigned char vref_value = 0x08; //只需要vref_value的[5:0]

	//#1: enter vref calibration mode
	Databahn_SetModeRegister6(0x80);
	stage1_delay_us(1); //150ns is enough

	//#2: set vref
	Databahn_SetModeRegister6(0x80|(vref_value & 0x3F));
	stage1_delay_us(1); //150ns is enough

	//#3: quit vref calibration mode
	Databahn_SetModeRegister6(0x0);
	stage1_delay_us(1); //150ns is enough
}

/* databahn.c */
void Databahn_Init(void)
{
	unsigned int i;
	unsigned int ddr_version;
	unsigned int tsel_feed;
	unsigned int data_e_sel;
	unsigned int ocd_pu_clk;
	unsigned int ocd_pd_clk;
	unsigned int ocd_pu_cmd;
	unsigned int ocd_pd_cmd;
	unsigned int dfi_cmd_control;
	unsigned int vref_set;
	unsigned int ddr_vref_en;
	unsigned int cwl;
	unsigned int encry_delay;
	unsigned int ddr_vref_cfg;
	unsigned int phy_ddrp_vref_cfg;
	unsigned int phy_ddrb_vref_cfg;
	unsigned int phy_ddrb_vref_en;
	unsigned int phy_ddrp_vref_en;
#ifdef CHIP_BOARD_6631SHXD
	unsigned char ddr_info = otp_read_simple(0x1B8);
#endif
	unsigned int *p_DENALI_CONFIG_CTL;
	unsigned int *p_DENALI_CONFIG_PHY;

	p_DENALI_CONFIG_CTL = DENALI_CONFIG_CTL;
	p_DENALI_CONFIG_PHY = DENALI_CONFIG_PHY;
#ifdef CHIP_BOARD_6631SHXD
	if ((ddr_info & 0xF) == 0x3) {
		if ((ddr_info & 0xF0) == 0x80) {
			/* DDR3-128 */
			serial_put_no_mmu('1');
			p_DENALI_CONFIG_CTL = DENALI_CONFIG_CTL_2;
			p_DENALI_CONFIG_PHY = DENALI_CONFIG_PHY_2;
		} else {
			/* DDR3-256 */
			serial_put_no_mmu('2');
			p_DENALI_CONFIG_CTL = DENALI_CONFIG_CTL_3;
			p_DENALI_CONFIG_PHY = DENALI_CONFIG_PHY_3;
		}
	} else {
			serial_put_no_mmu('5');
	}
#endif
	//===========clk&rst use sec_config!!!=====================
	/* set ddrc_clk */
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_CLOCK_SOURCE_SEC) |= (1<<17);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_CLOCK_GATE_REG_SEC) &= ~((1<<27)|(1<<28));

	/* reset ddrc */
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_COLD_RESET_REG_SEC) |= (0x1);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_COLD_RESET_REG_SEC) &= ~(0x1);

	/* set ddrc_ports */
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DENALI_CONFIG0)=0xffffffff;

	//============set dram_config0-7: begin===================
	//clear config0-7
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG3)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG4)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG5)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG6)=0x0;
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG7)=0x0;

	//#1: config1[31:29], set ddr_version
#ifdef CONFIG_DDR3
#ifdef DDR_SIP
	ddr_version = 0x2;
#else
	ddr_version = 0x3;
#endif
#elif defined(CONFIG_DDR2)
	ddr_version = 0x1;
#elif defined(CONFIG_DDR4)
	ddr_version = 0x4;
#else
#error "DDR_POS error"
#endif


#ifdef CHIP_BOARD_6631SHXD
	/* set DDR3 */
	if ((ddr_info & 0xF) == 0x3) {
		ddr_version = 0x2;
	}
#endif

	//#2: config0[2:0], tsel_feed
	tsel_feed = 0x1;

	//#3: config0[15], data_e_sel, choose the switch of the receiver in DDRIO
	//data_e_sel=0 means switch is controlled by DRAM_CONFIG0[14:11]
	data_e_sel = 0x0;

	//#4: ocd_pu&ocd_pd
	ocd_pu_clk = 0x8;
	ocd_pd_clk = 0x8;
	ocd_pu_cmd = 0x8;
	ocd_pd_cmd = 0x8;

	//#5: set output driver_strength of DDRIO in board_init.c
	ddr_config_patch();

	//#6: config0[31], dfi_cmd_control
	dfi_cmd_control = 0x1;

	//#7: config2[19:16], set SMIC_DDRIO's Vref
	vref_set = 0x0;

	//#8: config3[1:0], set encry_delay
	cwl = (p_DENALI_CONFIG_CTL[5] >> 16) & 0x1F;
	encry_delay = (cwl - 4) / 2;

	//#9: config7, set reserved vref on decap
	ddr_vref_cfg      = 0;
	phy_ddrp_vref_cfg = 0;
	phy_ddrb_vref_cfg = 0;
	phy_ddrb_vref_en  = 0;
	phy_ddrp_vref_en  = 0;
	ddr_vref_en       = 0;

	//set DRAM_CONFIG
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG0) |= (tsel_feed<<0) | (data_e_sel<<15) | (dfi_cmd_control<<31);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG1) |= (ocd_pu_clk<<3) | (ocd_pd_clk<<7) | (ocd_pu_clk<<14) | (ocd_pd_clk<<18) | (ddr_version<<29);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG2) |= (ocd_pu_cmd<<3) | (ocd_pd_cmd<<7) | (vref_set<<16);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG3) |= (encry_delay<<0);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG4) |= (ocd_pu_clk<<0) | (ocd_pd_clk<<4) | (ocd_pu_clk<<8) | (ocd_pd_clk<<12) | (ocd_pu_clk<<16) | (ocd_pd_clk<<20) | (ocd_pu_clk<<24) | (ocd_pd_clk<<28);
	*(volatile unsigned int*)(CONFIG_BASE+CONFIG_DRAM_CONFIG7) |= (ddr_vref_cfg<<0) | (phy_ddrp_vref_cfg<<8) | (phy_ddrb_vref_cfg<<16) | (phy_ddrb_vref_en<<29) | (phy_ddrp_vref_en<<30) | (ddr_vref_en<<31);
	//============set dram_config0-7: end===========

	for(i = 0;i < sizeof(DENALI_CONFIG_CTL)/sizeof(unsigned int); i++)
		*(volatile unsigned int *)Databahn_Reg(i) = p_DENALI_CONFIG_CTL[i];

	for(i = 0; i < sizeof(DENALI_CONFIG_PHY)/sizeof(unsigned int); i++)
		*(volatile unsigned int *)Databahn_Reg((i + 256)) = p_DENALI_CONFIG_PHY[i];

	Databahn_Config();

	if (ddr_version == 0x4)
		Databahn_SetDDR4Vref();

	while(!Databahn_isReady());
}

void Databahn_SetParameters(struct reg_param *regs, int count) {
	int i;

	for (i=0; i < count; i++)
		SetRegisterField(Databahn_Reg(regs[i].reg), regs[i].offset, regs[i].width, regs[i].value);
}

