static void Databahn_ConfigOTPParam(void)
{
	unsigned char otp_data[OTP_DRAM_PARAM_LEN];
	int i = 0;
	int otp_start_addr = 0x1B9;

	/* 0x1B9 ~ 0x1BF and 0x1CC ~ 0x1CD */
	for (i = 0; i < OTP_DRAM_PARAM_LEN; i++) {
		otp_data[i] = otp_read_simple(otp_start_addr);
		otp_start_addr++;
		if (otp_start_addr == 0x1C0)
			otp_start_addr = 0x1CC;
	}

	if ((otp_data[0] & 1) == 1 &&
	    ((otp_data[0] >> 1) & 0xF) == 0) {
		for (i = 0; i < sizeof(param_mode0) / sizeof(struct otp_dram_param); i++) {
			unsigned char val = 0;
			if (param_mode0[i].otp_data_byte_index > OTP_DRAM_PARAM_LEN - 1) {
				serial_put_no_mmu('e');
				while (1);
			}
			val = otp_data[param_mode0[i].otp_data_byte_index] >> param_mode0[i].otp_data_bit_offset;
			val &= (1 << param_mode0[i].reg_bit_width) - 1;
			SetRegisterField(param_mode0[i].reg_addr, param_mode0[i].reg_offset, \
					 param_mode0[i].reg_bit_width, val);
		}
		/* pvref_set */
		SetRegisterField(CONFIG_BASE+CONFIG_DRAM_CONFIG2, 16, 4, (otp_data[2] & 0x80) == 0x80 ? 0xa : 0x0);
	}
}
#endif

void Databahn_Config(void)
{
	Databahn_SetParameters(param_table, sizeof(param_table) / sizeof(struct reg_param));

#ifdef DDR_SIP
	Databahn_ConfigOTPParam();
#endif
	// Databahn start enable
	SetRegisterField(Databahn_Reg(DATABAHN_REG_START_ADDR), DATABAHN_REG_START_OFFSET, DATABAHN_REG_START_WIDTH, 1);
}

unsigned int Databahn_GetParameter(unsigned int reg, unsigned int offset, unsigned int width)
{
	return GetRegisterField(Databahn_Reg(reg), offset, width);
}

unsigned int Databahn_GetIntStatus(void)
{
	return Databahn_GetParameter(DATABAHN_REG_INT_STATUS_ADDR, DATABAHN_REG_INT_STATUS_OFFSET, DATABAHN_REG_INT_STATUS_WIDTH);
}

unsigned int Databahn_isReady(void)
{
	return (Databahn_GetIntStatus() & 0x20) ? 1 : 0;
}

static void wait_rng_ready(void)
{
	*(volatile unsigned int*)(CONFIG_BASE + CONFIG_RNG_CTRL) |= 1;
	while (!((*(volatile unsigned int*)(CONFIG_BASE + CONFIG_RNG_CTRL)) & 0x2));
	*(volatile unsigned int*)(CONFIG_BASE + CONFIG_RNG_CTRL) &= ~1;
}

void gx_setup_sdram_controller(void)
{
#ifdef CONFIG_FPGA_BOARD
	serial_put_no_mmu('N');
	return;
#endif
	Databahn_Init();
	serial_put_no_mmu('N');

//#ifdef ENABLE_SECURE_ALIGN
	if ((*(volatile unsigned int*)(REG_BASE_OTP+0x0C)) & (0x1 << 10))//bit 10 to indicate ddr_content_scramble_enable
	{
		volatile unsigned int i = 0x10000;
		*(volatile unsigned int *)(CONFIG_BASE + CONFIG_RNG_CTRL) = 1;
		while(*(volatile unsigned int *)(CONFIG_BASE + CONFIG_RNG_CTRL) != 0x02);
		*(volatile unsigned int *)(CONFIG_BASE + CONFIG_RNG_DATA);
		while (i--) //delay 30 ms
			__asm__ volatile ("nop");
	}
//#endif

}

